18: export class CrudTipoInscripcionComponent implements OnInit{
19:   tipo_inscripcion_id!: number;
20:   niveles: NivelFormacion[] | undefined;
21:   
22: 
23:   @Input('tipo_periodo_id')
24:   set name(tipo_inscripcion_id: number) {
25:     this.tipo_inscripcion_id = tipo_inscripcion_id;
