33:   //regTipoInscripcion: any;
34:   clean!: boolean;
35: 
36:   constructor(private translate: TranslateService, 
37:     private inscripcionService: InscripcionService,
38:     private projectService: ProyectoAcademicoService,
39:     private popUpManager: PopUpManager) {
40:     this.formTipoInscripcion = FORM_TIPO_INSCRIPCION;
41:     this.nivel_load();
42:     this.translate.onLangChange.subscribe((event: LangChangeEvent) => {
43:       this.construirForm();
44:     });
45: }
46: 
47:   // constructor(private translate: TranslateService, 
48:   //   private inscripcionService: InscripcionService,
