56:   //     this.construirForm();
57:   //   });
58:   //  }
59: 
60:   construirForm() {
61:     this.formTipoInscripcion.titulo = this.translate.instant('tipo_inscripcion.sub_titulo');
62:     this.formTipoInscripcion.btn = this.translate.instant('GLOBAL.guardar');
63:     this.formTipoInscripcion.campos.forEach((campo: any) => {
64:       campo.label = this.translate.instant('GLOBAL.' + campo.label_i18n);
65:       campo.placeholder = this.translate.instant('GLOBAL.placeholder_' + campo.label_i18n);
66:       if (campo.etiqueta === 'select') {
67:         campo.opciones = this.niveles;
68:       }
69:     });
70:   }
71: 
72:   useLanguage(language: string) {
73:     this.translate.use(language);
74:   }
75: 
76:   nivel_load() {
77:     this.projectService.get('nivel_formacion?limit=0').subscribe(
78:       (response: any) => { // Update the type of the response parameter to 'any'
79:         const nivelFormacionResponse = response as NivelFormacion[]; // Cast the response to the expected type 'NivelFormacion[]'
80:         this.niveles = nivelFormacionResponse.filter(nivel => nivel.NivelFormacionPadreId === null);
81:         this.construirForm();
82:       },
83:       error => {
84:         this.popUpManager.showErrorToast(this.translate.instant('ERROR.general'));
85:       }
86:     );
87:   }
