89:   getIndexForm(nombre: String): number {
90:     for (let index = 0; index < this.formTipoInscripcion.campos.length; index++) {
91:       const element = this.formTipoInscripcion.campos[index];
92:       if (element.nombre === nombre) {
93:         return index
94:       }
95:     }
96:     return 0;
97:   }
