100:   public loadTipoInscripcion(): void {
101:     if (this.tipo_inscripcion_id !== undefined && this.tipo_inscripcion_id !== 0) {
102:       this.inscripcionService.get('tipo_inscripcion/?query=id:' + this.tipo_inscripcion_id)
103:         .subscribe((res: any) => {
104:           if (res !== null) {
105:             this.info_tipo_inscripcion = <TipoInscripcion>res[0];
106:           }
107:         });
108:     } else  {
109:       this.info_tipo_inscripcion = undefined;
110:       this.clean = !this.clean;
111:     }
112:   }
113: 
114:   updateTipoInscripcion(tipoInscripcion: any): void {
115: 
116:     const opt: any = {
117:       title: this.translate.instant('GLOBAL.actualizar'),
118:       text: this.translate.instant('tipo_inscripcion.seguro_actualizar_tipo_inscripcion'),
119:       icon: 'warning',
120:       showCancelButton: true,
121:     };
122:     Swal.fire(opt)
123:     .then((willDelete: any) => {
124:       if (willDelete.value) {
125:         if(tipoInscripcion['Activo'] == ''){
126:           tipoInscripcion.Activo = false;
127:         }
128:         if(tipoInscripcion['Especial'] == ''){
129:           tipoInscripcion.Especial = false;
130:         }
131:         tipoInscripcion.NivelId = tipoInscripcion['Nivel']['Id'];
132:         this.info_tipo_inscripcion = <TipoInscripcion>tipoInscripcion;
133:         this.inscripcionService.put('tipo_inscripcion', this.info_tipo_inscripcion)
134:           .subscribe(res => {
135:             this.loadTipoInscripcion();
136:             this.eventChange.emit(true);
137:             this.popUpManager.showSuccessAlert(this.translate.instant('tipo_inscripcion.tipo_inscripcion_actualizado'))
138:           });
139:       }
140:     });
141:   }
142: 
143:   createTipoInscripcion(tipoInscripcion: any): void {
144:     const opt: any = {
145:       title: this.translate.instant('GLOBAL.registrar'),
146:       text: this.translate.instant('tipo_inscripcion.seguro_continuar_registrar_tipo_inscripcion'),
147:       icon: 'warning',
148:       showCancelButton: true,
149:     };
150:     Swal.fire(opt)
151:     .then((willDelete: any) => {
152:       if (willDelete.value) {
153:         if(tipoInscripcion['Activo'] == ''){
154:           tipoInscripcion.Activo = false;
155:         }
156:         if(tipoInscripcion['Especial'] == ''){
157:           tipoInscripcion.Especial = false;
158:         }
159:         tipoInscripcion.NivelId = tipoInscripcion['Nivel']['Id'];
160:         this.info_tipo_inscripcion = <TipoInscripcion>tipoInscripcion;
161:         this.inscripcionService.post('tipo_inscripcion', this.info_tipo_inscripcion)
162:           .subscribe(res => {
163:             this.info_tipo_inscripcion = <TipoInscripcion><unknown>res;
164:             this.eventChange.emit(true);
165:             this.popUpManager.showSuccessAlert(this.translate.instant('tipo_periodo.tipo_periodo_creado'))
166:           });
167:       }
168:     });
169:   }
170: 
171:   ngOnInit() {
172:     this.loadTipoInscripcion();
173:   }
174: 
175:   validarForm(event: any) {
176:     if (event.valid) {
177:       if (this.info_tipo_inscripcion === undefined) {
178:         this.createTipoInscripcion(event.data.TipoInscripcion);
179:       } else {
180:         this.updateTipoInscripcion(event.data.TipoInscripcion);
181:       }
182:     }
183:   }
184: }
