39:   recuperarNivelesAcademicos() {
40:     return new Promise((resolve, reject) => {
41:       this.parametrosService.get('periodo/?query=CodigoAbreviacion:PA&sortby=Id&order=desc&limit=0').subscribe((res: any) => {
42:         resolve(res.Data);
43:       },
44:         (error: any) => {
