52:   recuperarParametroOPregrado() {
53:     return new Promise((resolve, reject) => {
54:       this.parametrosService.get('parametro?query=Activo:true,CodigoAbreviacion:OPREGRADO').subscribe((res: any) => {
55:         resolve(res.Data);
56:       },
57:         (error: any) => {
58:           console.error(error);
59:           this.popUpManager.showErrorToast(this.translate.instant('ERROR.general'));
60:           reject(error);
61:         });
62:     });
63:   }
64: 
65:   recuperarNivelParametro(periodoId: any, parametroId: any) {
66:     return new Promise((resolve, reject) => {
67:       this.parametrosService.get('parametro_periodo/?query=PeriodoId:' + periodoId + ',ParametroId:' + parametroId + ',Activo:true&sortby=Id&order=desc&limit=0').subscribe((res: any) => {
68:         if (res.Status === "200") {
69:           resolve(res.Data);
70:         } else {
71:           this.popUpManager.showErrorToast(this.translate.instant('ERROR.general'));
72:           reject(false);
73:         }
74:       },
75:         (error: any) => {
76:           console.error(error);
77:           this.popUpManager.showErrorToast(this.translate.instant('ERROR.general'));
78:           reject(error);
79:         });
80:     });
81:   }
