83:   async selectNivel() {
84:     const nivel: any = await this.recuperarNivelParametro(this.nivel, this.parametro_id);
85:     if (this.isObjectEmpty(nivel[0]) === false) {
86:       this.opciones = JSON.parse(nivel[0].Valor).Valor;
87:     }else{
88:       this.opciones = '';
89:     }
