56:       for (let i = 0; i < data.length; i += chunkSize) {
57:         const chunk = data.slice(i, i + chunkSize);
58:         const worksheet = XLSX.utils.json_to_sheet(chunk);
59:         XLSX.utils.book_append_sheet(workbook, worksheet, `Sheet${Math.floor(i / chunkSize) + 1}`);
60:       }
